static FJediProceduralBone MakeBone(const TCHAR* Name, float Share = 0.f)
{
	FJediProceduralBone B; B.BoneName = Name; B.SpineShare = Share; return B;
}
static FRotator ScaleRot(const FRotator& R, float S) { return FRotator(R.Pitch * S, R.Yaw * S, R.Roll * S); }
static FRotator InterpRot(const FRotator& Cur, const FRotator& Target, float Dt, float Speed)
{
	// per-axis FInterpTo on unwound angles: no quaternion flips, exponential ease toward the target
	return FRotator(FMath::FInterpTo(Cur.Pitch, Target.Pitch, Dt, Speed),
	                FMath::FInterpTo(Cur.Yaw, Target.Yaw, Dt, Speed),
	                FMath::FInterpTo(Cur.Roll, Target.Roll, Dt, Speed));
}

AJediCombatCharacter::AJediCombatCharacter()
{
	PrimaryActorTick.bCanEverTick = true;
	GetCapsuleComponent()->InitCapsuleSize(36.f, 92.f);

	// the Duke packs face +Y after FBX import: turn the mesh to the actor's +X, feet on the capsule bottom
	GetMesh()->SetRelativeLocationAndRotation(FVector(0.f, 0.f, -92.f), FRotator(0.f, -90.f, 0.f));
	GetMesh()->SetAnimInstanceClass(UDukeTrooperAnimInstance::StaticClass());

	bUseControllerRotationPitch = bUseControllerRotationYaw = bUseControllerRotationRoll = false;
	UCharacterMovementComponent* Move = GetCharacterMovement();
	Move->bOrientRotationToMovement = true;
	Move->RotationRate = FRotator(0.f, 540.f, 0.f);
	Move->MaxWalkSpeed = WalkSpeed;
	// the input spring does the easing; keep the movement component responsive so the two do not stack into mush
	Move->MaxAcceleration = 2400.f;
	Move->BrakingDecelerationWalking = 2000.f;
	Move->GroundFriction = 8.f;
	Move->bUseSeparateBrakingFriction = false;

	CameraBoom = CreateDefaultSubobject<USpringArmComponent>(TEXT("CameraBoom"));
	CameraBoom->SetupAttachment(RootComponent);
	CameraBoom->TargetArmLength = 330.f;
	CameraBoom->SocketOffset = FVector(0.f, 45.f, 55.f);
	CameraBoom->bUsePawnControlRotation = true;
	CameraBoom->bEnableCameraLag = true;
	CameraBoom->CameraLagSpeed = 12.f;
	FollowCamera = CreateDefaultSubobject<UCameraComponent>(TEXT("FollowCamera"));
	FollowCamera->SetupAttachment(CameraBoom, USpringArmComponent::SocketName);
	FollowCamera->bUsePawnControlRotation = false;

	MotionWarping = CreateDefaultSubobject<UMotionWarpingComponent>(TEXT("MotionWarping"));

	// torso rotation spread over three spine joints; shares sum to 1 so the chest reaches the full angle
	UpperBodyPose.Spine = { MakeBone(TEXT("spine_01"), 0.25f), MakeBone(TEXT("spine_02"), 0.35f), MakeBone(TEXT("spine_03"), 0.40f) };
	UpperBodyPose.ClavicleL = MakeBone(TEXT("clavicle_l"));
	UpperBodyPose.ClavicleR = MakeBone(TEXT("clavicle_r"));
	UpperBodyPose.Neck = MakeBone(TEXT("neck_01"));

	// the Duke Jedi combo (strike frames from tools/rigging/jedi_clips.py); swap in authored montages per step
	auto Step = [](const TCHAR* Clip, float Strike, FVector2D Dir) { FJediComboStep S; S.Clip = Clip; S.StrikeTime = Strike; S.SwingDirection = Dir; return S; };
	ComboSteps = {
		Step(TEXT("saber_attack_1"), 0.42f, FVector2D(-1.f, -0.4f)),   // backhand, left to right, slightly down
		Step(TEXT("saber_attack_2"), 0.40f, FVector2D(1.f, 0.8f)),     // rising slash from the sword side
		Step(TEXT("saber_attack_3"), 0.50f, FVector2D(0.3f, -1.f)),    // overhead
		Step(TEXT("saber_thrust"), 0.38f, FVector2D::ZeroVector) };    // thrust: forward lean only
}

UDukeTrooperAnimInstance* AJediCombatCharacter::DukeAnim() const
{
	return Cast<UDukeTrooperAnimInstance>(GetMesh()->GetAnimInstance());
}

void AJediCombatCharacter::BeginPlay()
{
	Super::BeginPlay();
	if (!GetMesh()->GetSkeletalMeshAsset())
		if (USkeletalMesh* SK = LoadObject<USkeletalMesh>(nullptr, *FString::Printf(TEXT("%s/SK_Trooper.SK_Trooper"), *AssetPath)))
		{
			GetMesh()->SetSkeletalMesh(SK);
			const float H = SK->GetBounds().BoxExtent.Z * 2.f;   // authored at 1.83 m: correct a unit mismatch from import
			if (H > 1.f && FMath::Abs(H - 183.f) > 15.f) GetMesh()->SetRelativeScale3D(FVector(183.f / H));
		}
	GetMesh()->SetAnimInstanceClass(UDukeTrooperAnimInstance::StaticClass());
	const int32 N = UDukeTrooperAnimInstance::LoadClipSet(DukeAnim(), AssetPath, ADukeTrooper::ClipNames());
	UE_LOG(LogTemp, Log, TEXT("JediCombatCharacter %s: %d clips from %s"), *GetName(), N, *AssetPath);
	GetCharacterMovement()->MaxWalkSpeed = WalkSpeed;
	LastVelocity = GetVelocity();
}

void AJediCombatCharacter::SetupPlayerInputComponent(UInputComponent* PlayerInputComponent)
{
	Super::SetupPlayerInputComponent(PlayerInputComponent);   // Strike (virtual OnStrike), Interact, Holster
	if (UEnhancedInputComponent* EIC = Cast<UEnhancedInputComponent>(PlayerInputComponent))
	{
		if (MoveAction)
		{
			EIC->BindAction(MoveAction, ETriggerEvent::Triggered, this, &AJediCombatCharacter::Move);
			EIC->BindAction(MoveAction, ETriggerEvent::Completed, this, &AJediCombatCharacter::MoveReleased);
		}
		if (LookAction) EIC->BindAction(LookAction, ETriggerEvent::Triggered, this, &AJediCombatCharacter::Look);
		if (SprintAction)
		{
			EIC->BindAction(SprintAction, ETriggerEvent::Started, this, &AJediCombatCharacter::SprintStarted);
			EIC->BindAction(SprintAction, ETriggerEvent::Completed, this, &AJediCombatCharacter::SprintEnded);
		}
	}
}

void AJediCombatCharacter::Move(const FInputActionValue& Value)
{
	const FVector2D V = Value.Get<FVector2D>();            // Enhanced Input convention: X right, Y forward
	RawMoveInput = FVector2D(V.Y, V.X).GetClampedToMaxSize(1.f);   // stored as X forward, Y right
}
void AJediCombatCharacter::MoveReleased(const FInputActionValue&) { RawMoveInput = FVector2D::ZeroVector; }
void AJediCombatCharacter::Look(const FInputActionValue& Value)
{
	const FVector2D V = Value.Get<FVector2D>();
	AddControllerYawInput(V.X);
	AddControllerPitchInput(V.Y);
}
void AJediCombatCharacter::SprintStarted(const FInputActionValue&) { bSprintHeld = true; }
void AJediCombatCharacter::SprintEnded(const FInputActionValue&) { bSprintHeld = false; }

void AJediCombatCharacter::Tick(float DeltaSeconds)
{
	Super::Tick(DeltaSeconds);
	if (DeltaSeconds <= KINDA_SMALL_NUMBER) return;
	UpdateLocomotion(DeltaSeconds);
	TickStrike(DeltaSeconds);
	UpdateUpperBody(DeltaSeconds);
	PushAnimState();
}

// ---------------- 2. damped locomotion ----------------
// A critically damped spring per axis (no overshoot, continuous velocity). Its stiffness switches between
// acceleration, deceleration and reversal rates, but the spring's velocity carries over, so a change of rate never
// produces a kink. A reversal is the slowest: the body plants and turns instead of snapping to the new direction.
void AJediCombatCharacter::UpdateLocomotion(float Dt)
{
	const FVector2D Target = RawMoveInput;
	float Rate;
	if (Target.SizeSquared() < 0.0004f) Rate = InputDecelerationRate;
	else if (FVector2D::DotProduct(Target, SmoothedMoveInput) < 0.f) Rate = InputReversalRate;
	else if (Target.SizeSquared() >= SmoothedMoveInput.SizeSquared()) Rate = InputAccelerationRate;
	else Rate = InputDecelerationRate;

	const float K = Rate * Rate, C = 2.f * Rate;
	const int32 Steps = FMath::Clamp(FMath::CeilToInt(Dt * 240.f), 1, 16);   // fixed small sub-steps: stable at any frame rate
	const float H = Dt / Steps;
	for (int32 i = 0; i < Steps; ++i)
	{
		const FVector2D Acc = (Target - SmoothedMoveInput) * K - InputVelocity * C;
		InputVelocity += Acc * H;
		SmoothedMoveInput += InputVelocity * H;   // semi-implicit Euler
	}
	SmoothedMoveInput = SmoothedMoveInput.GetClampedToMaxSize(1.f);
	if (Target.IsNearlyZero() && SmoothedMoveInput.SizeSquared() < 1e-4f) { SmoothedMoveInput = FVector2D::ZeroVector; InputVelocity = FVector2D::ZeroVector; }

	// drive movement with the smoothed input, relative to the camera's yaw
	if (Controller && !SmoothedMoveInput.IsNearlyZero(0.01f))
	{
		const FRotator Yaw(0.f, Controller->GetControlRotation().Yaw, 0.f);
		AddMovementInput(FRotationMatrix(Yaw).GetUnitAxis(EAxis::X), SmoothedMoveInput.X);
		AddMovementInput(FRotationMatrix(Yaw).GetUnitAxis(EAxis::Y), SmoothedMoveInput.Y);
	}

	// sprint: forward-ish input held, eased speed change
	const bool bAttacking = GetMesh()->GetAnimInstance() && GetMesh()->GetAnimInstance()->IsAnyMontagePlaying();
	bIsSprinting = bSprintHeld && !bAttacking && SmoothedMoveInput.Size() > 0.6f;
	UCharacterMovementComponent* Move = GetCharacterMovement();
	Move->MaxWalkSpeed = FMath::FInterpTo(Move->MaxWalkSpeed, bIsSprinting ? SprintSpeed : WalkSpeed, Dt, 4.f);

	// blend-space variables (smoothed again so a one-frame velocity spike never pops the blend)
	const FVector Local = GetActorRotation().UnrotateVector(GetVelocity());
	GroundSpeed = FMath::FInterpTo(GroundSpeed, Local.Size2D(), Dt, BlendVariableInterpSpeed);
	if (Local.Size2D() > 10.f)
	{
		const float TargetDir = FMath::RadiansToDegrees(FMath::Atan2(Local.Y, Local.X));
		LocomotionDirection = FRotator::NormalizeAxis(LocomotionDirection + FMath::FInterpTo(0.f, FMath::FindDeltaAngleDegrees(LocomotionDirection, TargetDir), Dt, BlendVariableInterpSpeed));
	}
	bIsAccelerating = Move->GetCurrentAcceleration().SizeSquared() > 1.f;
}

// ---------------- 1. procedural shoulder and spine compensation ----------------
float AJediCombatCharacter::SwingEnvelope(float P)
{
	// wind-up against the swing (-0.4), then the strike and follow-through (+1, peaking at ~0.65): continuous at 0.3
	if (P <= 0.f || P >= 1.f) return 0.f;
	if (P < 0.3f) return -0.4f * FMath::Sin(PI * P / 0.3f);
	return FMath::Sin(PI * (P - 0.3f) / 0.7f);
}

void AJediCombatCharacter::UpdateUpperBody(float Dt)
{
	const FVector V = GetVelocity();
	const FVector LocalAccel = GetActorRotation().UnrotateVector((V - LastVelocity) / Dt);
	LastVelocity = V;
	const float Speed = V.Size2D();
	const bool bAttacking = SwingClock >= 0.f;
	const float LocoScale = bAttacking ? AttackLocomotionLeanScale : 1.f;
	const bool bGrounded = !GetCharacterMovement()->IsFalling();

	// sprint lean grows from jog to sprint; forward acceleration adds to it, braking pulls the chest back
	const float SprintAlpha = FMath::Clamp((Speed - WalkSpeed * 0.5f) / FMath::Max(SprintSpeed - WalkSpeed * 0.5f, 1.f), 0.f, 1.f);
	float TargetPitch = MaxSprintLeanPitch * SprintAlpha + FMath::Clamp(LocalAccel.X / 1000.f * AccelLeanPitchPerG, -6.f, 6.f);
	// bank into turns: centripetal (lateral) acceleration, scaled by speed so standing pivots do not tilt
	float TargetRoll = FMath::Clamp(LocalAccel.Y / 1000.f * BankPerLateralG, -MaxBankRoll, MaxBankRoll) * FMath::Clamp(Speed / FMath::Max(WalkSpeed, 1.f), 0.f, 1.f);
	if (!bGrounded) { TargetPitch *= 0.3f; TargetRoll *= 0.3f; }
	TargetPitch *= LocoScale; TargetRoll *= LocoScale;

	// swing: twist away (wind-up), then rotate through the cut; the chest leads, the hips follow (via the shares)
	float TargetYaw = 0.f, ClavLift = 0.f;
	if (bAttacking && SwingDuration > 0.f)
	{
		const float Env = SwingEnvelope(SwingClock / SwingDuration);
		if (ActiveSwingDir.IsNearlyZero()) TargetPitch += MaxSwingPitch * 0.6f * FMath::Max(Env, 0.f);   // thrust
		else
		{
			TargetYaw = -ActiveSwingDir.X * MaxSwingTwistYaw * Env;   // +X sweep (right to left): wind up right, cut left
			TargetPitch += -ActiveSwingDir.Y * MaxSwingPitch * Env;   // rising cut opens the chest, a downward cut folds it
		}
		ClavLift = ClavicleSwingLift * FMath::Abs(Env);
	}
	LeanPitch = FMath::FInterpTo(LeanPitch, TargetPitch, Dt, SpineInterpSpeed);
	LeanRoll = FMath::FInterpTo(LeanRoll, TargetRoll, Dt, SpineInterpSpeed);
	const float Yaw = FMath::FInterpTo(UpperBodyPose.TorsoTotal.Yaw, TargetYaw, Dt, SpineInterpSpeed);
	// FRotator: + Pitch tips the chest BACK, so a forward lean is negative pitch; + Roll banks to the right
	UpperBodyPose.TorsoTotal = FRotator(-LeanPitch, Yaw, LeanRoll);

	float ShareSum = 0.f; for (const FJediProceduralBone& B : UpperBodyPose.Spine) ShareSum += B.SpineShare;
	for (FJediProceduralBone& B : UpperBodyPose.Spine)
		B.Rotation = ScaleRot(UpperBodyPose.TorsoTotal, ShareSum > 0.f ? B.SpineShare / ShareSum : 0.f);

	// clavicles: the sword (right) shoulder rides up and forward through the cut; both roll forward at speed.
	// Right clavicle: up = -Roll, forward = -Yaw. Left clavicle mirrors (up = +Roll, forward = +Yaw).
	const float Fwd = ClavicleSprintForward * SprintAlpha * LocoScale;
	const FRotator TargetR(0.f, -(Fwd + ClavLift * 0.6f), -ClavLift);
	const FRotator TargetL(0.f, Fwd - ClavLift * 0.25f, ClavLift * 0.2f);   // off hand counter-balances, slightly back
	UpperBodyPose.ClavicleR.Rotation = InterpRot(UpperBodyPose.ClavicleR.Rotation, TargetR, Dt, ClavicleInterpSpeed);
	UpperBodyPose.ClavicleL.Rotation = InterpRot(UpperBodyPose.ClavicleL.Rotation, TargetL, Dt, ClavicleInterpSpeed);

	// neck: cancel part of the torso motion so the eyes stay level and on the target (no bobble-head)
	UpperBodyPose.Neck.Rotation = InterpRot(UpperBodyPose.Neck.Rotation, ScaleRot(UpperBodyPose.TorsoTotal, -NeckStabilization), Dt, NeckInterpSpeed);
}

void AJediCombatCharacter::PushAnimState()
{
	UDukeTrooperAnimInstance* A = DukeAnim();
	if (!A) return;
	const FVector Local = GetActorRotation().UnrotateVector(GetVelocity());
	A->State.LocalVelocity = FVector(Local.X, Local.Y, 0.f);
	A->State.bFalling = GetCharacterMovement()->IsFalling();
	ADukeLightsaberWeapon* Saber = Cast<ADukeLightsaberWeapon>(CurrentEquippedWeapon);
	A->State.bAiming = Saber && Saber->bIsBladeActive;   // saber guard locomotion while lit
	if (Controller)
	{
		const FRotator Ctrl = Controller->GetControlRotation();
		const float LookYaw = FMath::Clamp(FRotator::NormalizeAxis(Ctrl.Yaw - GetActorRotation().Yaw), -70.f, 70.f);
		const float LookPitch = FMath::Clamp(FRotator::NormalizeAxis(Ctrl.Pitch), -40.f, 40.f);
		const float Dt = GetWorld()->GetDeltaSeconds();
		A->State.LookYaw = FMath::FInterpTo(A->State.LookYaw, LookYaw, Dt, 4.f);
		A->State.LookPitch = FMath::FInterpTo(A->State.LookPitch, LookPitch, Dt, 4.f);
	}
	A->State.MeshToActor = GetMesh()->GetRelativeRotation().Quaternion();
	A->State.ProceduralBones.Reset();
	if (!bApplyProceduralUpperBody) return;
	auto Push = [A](const FJediProceduralBone& B) { if (!B.BoneName.IsNone()) A->State.ProceduralBones.Add({ B.BoneName, B.Rotation.Quaternion() }); };
	for (const FJediProceduralBone& B : UpperBodyPose.Spine) Push(B);
	Push(UpperBodyPose.ClavicleL); Push(UpperBodyPose.ClavicleR); Push(UpperBodyPose.Neck);
}

// ---------------- 3. motion-warped saber strikes ----------------
bool AJediCombatCharacter::IsHostile(const AActor* Actor) const
{
	if (const ADukeTrooper* T = Cast<ADukeTrooper>(Actor)) return !T->IsDead() && T->Faction != EDukeFaction::Alliance;
	if (const ADukeSmartNPC* N = Cast<ADukeSmartNPC>(Actor))
		return N->CurrentState != EDukeNpcState::Dead && !N->bIsRecruited && (N->bIsEnemyFaction || N->TargetPlayerRef == this);
	return false;
}

AActor* AJediCombatCharacter::FindStrikeTarget() const
{
	UWorld* W = GetWorld(); if (!W) return nullptr;
	// aim along the stick if it is pushed, else along the camera
	FVector Aim;
	const FRotator Yaw(0.f, Controller ? Controller->GetControlRotation().Yaw : GetActorRotation().Yaw, 0.f);
	if (RawMoveInput.Size() > 0.2f) Aim = FRotationMatrix(Yaw).GetUnitAxis(EAxis::X) * RawMoveInput.X + FRotationMatrix(Yaw).GetUnitAxis(EAxis::Y) * RawMoveInput.Y;
	else Aim = Yaw.Vector();
	Aim = Aim.GetSafeNormal2D();

	TArray<FOverlapResult> Hits;
	FCollisionQueryParams Q(SCENE_QUERY_STAT(JediStrikeTarget), false, this);
	W->OverlapMultiByObjectType(Hits, GetActorLocation(), FQuat::Identity, FCollisionObjectQueryParams(ECC_Pawn), FCollisionShape::MakeSphere(TargetSearchRadius), Q);
	AActor* Best = nullptr; float BestScore = TNumericLimits<float>::Max();
	const float CosHalf = FMath::Cos(FMath::DegreesToRadians(TargetSearchHalfAngle));
	for (const FOverlapResult& H : Hits)
	{
		AActor* A = H.GetActor();
		if (!A || A == this || !IsHostile(A)) continue;
		FVector To = A->GetActorLocation() - GetActorLocation(); To.Z = 0.f;
		const float Dist = To.Size(); if (Dist < 1.f) return A;
		const float Cos = FVector::DotProduct(To / Dist, Aim);
		if (Cos < CosHalf) continue;
		const float Score = Dist / TargetSearchRadius + (1.f - Cos) * 1.5f;   // close and in front wins
		if (Score < BestScore) { BestScore = Score; Best = A; }
	}
	return Best;
}

bool AJediCombatCharacter::UpdateSaberWarpTarget(AActor* Target)
{
	if (!MotionWarping) return false;
	if (!Target)
	{
		MotionWarping->RemoveWarpTarget(WarpTargetName);
		CurrentWarpTarget = nullptr; bGlide = false;
		return false;
	}
	const FVector Me = GetActorLocation();
	FVector To = Target->GetActorLocation() - Me; To.Z = 0.f;
	const float Dist = To.Size();
	const FVector Dir = Dist > 1.f ? To / Dist : GetActorForwardVector();
	const bool bInRange = Dist <= MaxWarpDistance;
	// stop at blade reach in front of the target; too far: stay put and only turn; too close: do not back-pedal
	WarpLocation = (bInRange && Dist > StrikeStandOff) ? Target->GetActorLocation() - Dir * StrikeStandOff : Me;
	WarpLocation.Z = Me.Z;
	MotionWarping->AddOrUpdateWarpTargetFromLocationAndRotation(WarpTargetName, WarpLocation, Dir.Rotation());
	CurrentWarpTarget = Target;
	return bInRange;
}

UAnimMontage* AJediCombatCharacter::MontageForStep(const FJediComboStep& Step)
{
	if (Step.Montage) return Step.Montage;
	if (const TObjectPtr<UAnimMontage>* M = DynamicMontages.Find(Step.Clip)) return *M;
	UDukeTrooperAnimInstance* A = DukeAnim(); if (!A) return nullptr;
	const TObjectPtr<UAnimSequence>* Seq = A->Clips.Find(Step.Clip);
	if (!Seq || !*Seq) return nullptr;
	UAnimMontage* M = UAnimMontage::CreateSlotAnimationAsDynamicMontage(Seq->Get(), UDukeTrooperAnimInstance::MontageSlot, 0.08f, 0.22f, 1.f, 1);
	if (M) DynamicMontages.Add(Step.Clip, M);
	return M;
}

bool AJediCombatCharacter::PerformSaberStrike()
{
	if (ComboSteps.Num() == 0) return false;
	const float Now = GetWorld()->GetTimeSeconds();
	if (Now - StrikeBusyUntil > ComboResetSeconds) ComboIndex = 0;   // paused too long: the combo starts over
	const FJediComboStep& Step = ComboSteps[ComboIndex % ComboSteps.Num()];
	UAnimMontage* M = MontageForStep(Step);
	if (!M) return false;
	++ComboIndex;

	AActor* Target = FindStrikeTarget();
	UpdateSaberWarpTarget(Target);
	const float Rate = FMath::Max(Step.PlayRate, 0.1f);
	bDynamicStep = Step.Montage == nullptr;
	if (bDynamicStep && MotionWarping)
	{
		// a dynamic montage has no Motion Warping notify state: add the warp window (start -> blade contact) in code
		URootMotionModifier_SkewWarp* Mod = NewObject<URootMotionModifier_SkewWarp>(MotionWarping);
		Mod->Animation = M; Mod->StartTime = 0.f; Mod->EndTime = Step.StrikeTime;
		Mod->WarpTargetName = WarpTargetName;
		Mod->bWarpTranslation = true; Mod->bIgnoreZAxis = true; Mod->bWarpRotation = true;
		MotionWarping->AddModifier(Mod);
	}
	// Skew warp scales the clip's own root travel. An in-place clip has none, so ease onto the same warp point here.
	const FVector RootTravel = UMotionWarpingUtilities::ExtractRootMotionFromAnimation(M, 0.f, Step.StrikeTime).GetTranslation();
	bGlide = Target && RootTravel.Size2D() < 5.f && FVector::Dist2D(WarpLocation, GetActorLocation()) > 5.f;
	GlideClock = 0.f; GlideDuration = Step.StrikeTime / Rate * 0.9f; GlideFrom = GetActorLocation();

	PlayAnimMontage(M, Rate);
	StrikeTimeScaled = Step.StrikeTime / Rate;
	SwingClock = 0.f; SwingDuration = StrikeTimeScaled / 0.6f; ActiveSwingDir = Step.SwingDirection;
	StrikeWindowStart = StrikeTimeScaled - 0.15f; StrikeWindowEnd = StrikeTimeScaled + 0.12f;
	StrikeBusyUntil = Now + StrikeTimeScaled + 0.18f;   // the next strike may cancel the recovery from here
	return true;
}

void AJediCombatCharacter::OnStrike()
{
	ADukeLightsaberWeapon* Saber = Cast<ADukeLightsaberWeapon>(CurrentEquippedWeapon);
	if (!Saber) { Super::OnStrike(); return; }   // blasters keep the base behaviour
	const float Now = GetWorld()->GetTimeSeconds();
	if (Now < StrikeBusyUntil)
	{
		if (Now >= StrikeBusyUntil - InputBufferSeconds) BufferedStrikeAt = Now;   // queued: fires at the cancel point
		return;
	}
	PerformSaberStrike();
}

void AJediCombatCharacter::TickStrike(float Dt)
{
	const float Now = GetWorld()->GetTimeSeconds();
	if (BufferedStrikeAt > 0.f && Now >= StrikeBusyUntil)
	{
		BufferedStrikeAt = -100.f;
		PerformSaberStrike();
	}
	if (SwingClock < 0.f) return;
	SwingClock += Dt;

	// keep tracking a moving target until blade contact, so the warp lands where the enemy is now
	if (CurrentWarpTarget && SwingClock < StrikeTimeScaled) UpdateSaberWarpTarget(CurrentWarpTarget);
	if (bGlide)
	{
		GlideClock += Dt;
		const float A = FMath::SmoothStep(0.f, 1.f, FMath::Clamp(GlideClock / FMath::Max(GlideDuration, 0.01f), 0.f, 1.f));
		FVector Want = FMath::Lerp(GlideFrom, WarpLocation, A); Want.Z = GetActorLocation().Z;
		AddActorWorldOffset(Want - GetActorLocation(), true);   // swept: never pushes through the target or walls
		if (GlideClock >= GlideDuration) bGlide = false;
	}
	// Duke clips carry no saber notify state: open the blade trace around the strike frame here
	if (bDynamicStep)
		if (ADukeLightsaberWeapon* Saber = Cast<ADukeLightsaberWeapon>(CurrentEquippedWeapon))
			Saber->bPhysicsDetectionAllowed = SwingClock >= StrikeWindowStart && SwingClock <= StrikeWindowEnd;
	if (SwingClock >= SwingDuration)
	{
		SwingClock = -1.f; bGlide = false;
		if (bDynamicStep) if (ADukeLightsaberWeapon* Saber = Cast<ADukeLightsaberWeapon>(CurrentEquippedWeapon)) Saber->bPhysicsDetectionAllowed = false;
	}
}
